import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { performance } from 'node:perf_hooks';
import { parseFile } from '../src/index.js';
const SAMPLE_PATH = join(process.cwd(), 'sample.fit');
const percentile = (values, p) => {
    if (values.length === 0)
        return 0;
    const sorted = [...values].sort((a, b) => a - b);
    const index = Math.min(sorted.length - 1, Math.max(0, Math.ceil((p / 100) * sorted.length) - 1));
    return sorted[index];
};
async function naiveBaseline(buffer) {
    const perEventLatencies = [];
    const start = performance.now();
    const events = [];
    for (let index = 0; index < buffer.length; index += 1) {
        const eventStart = performance.now();
        events.push({ metric: `byte_${index}`, value: buffer[index] ?? 0 });
        perEventLatencies.push(performance.now() - eventStart);
    }
    const elapsedMs = performance.now() - start;
    const rss = process.memoryUsage().rss;
    return {
        events: events.length,
        elapsedMs,
        throughput: events.length / Math.max(elapsedMs, 1) * 1000,
        rss,
        p99: percentile(perEventLatencies, 99),
    };
}
async function realParserBenchmark(buffer) {
    const perEventLatencies = [];
    const start = performance.now();
    let count = 0;
    for await (const event of parseFile(buffer)) {
        const eventStart = performance.now();
        count += 1;
        perEventLatencies.push(performance.now() - eventStart);
    }
    const elapsedMs = performance.now() - start;
    return {
        events: count,
        elapsedMs,
        throughput: count / Math.max(elapsedMs, 1) * 1000,
        rss: process.memoryUsage().rss,
        p99: percentile(perEventLatencies, 99),
    };
}
async function main() {
    const sample = readFileSync(SAMPLE_PATH);
    const actual = await realParserBenchmark(new Uint8Array(sample));
    const naive = await naiveBaseline(new Uint8Array(sample));
    const rows = [
        ['telemetry-stream-parser', actual.events.toString(), `${actual.throughput.toFixed(0)} events/sec`, `${(actual.rss / 1024 / 1024).toFixed(1)} MB`, `${actual.p99.toFixed(3)} ms`],
        ['naive baseline', naive.events.toString(), `${naive.throughput.toFixed(0)} events/sec`, `${(naive.rss / 1024 / 1024).toFixed(1)} MB`, `${naive.p99.toFixed(3)} ms`],
    ];
    const table = `# Benchmarks\n\nThe benchmark uses the Garmin sample in this package. All numbers are generated by running \`npm run bench\` from the package root.\n\n| Parser | Events | Throughput | Peak RSS | p99 latency |\n|---|---:|---:|---:|---:|\n| telemetry-stream-parser | ${rows[0][1]} | ${rows[0][2]} | ${rows[0][3]} | ${rows[0][4]} |\n| naive baseline | ${rows[1][1]} | ${rows[1][2]} | ${rows[1][3]} | ${rows[1][4]} |\n`;
    writeFileSync(join(process.cwd(), 'BENCHMARKS.md'), table);
    console.log(table);
}
main().catch((error) => {
    console.error(error);
    process.exit(1);
});
